parameters.jsCode:
// Get extracted data
const contractValue = parseFloat($input.first().json.output.contractValue) || 0;
const urgency = $input.first().json.output.urgency;
const riskFlags = $input.first().json.output.riskFlags;
const documentType = $input.first().json.output.documentType;
const renewalDate = $input.first().json.output.renewalDate;

// Determine status
let status = 'Pending Review';
let alertPriority = 'Medium';
let routeToEmail = 'general@company.com';

// High priority conditions
if (contractValue > 50000) {
  alertPriority = 'High';
  status = 'Requires Executive Approval';
  routeToEmail = 'ceo@company.com, legal@company.com';
} else if (urgency === 'High') {
  alertPriority = 'High';
} else if (riskFlags && riskFlags.length > 0) {
  alertPriority = 'High';
  routeToEmail = 'legal@company.com';
}

// Route based on document type
if (documentType && documentType.toLowerCase().includes('invoice')) {
  routeToEmail = 'finance@company.com';
  alertPriority = 'Low';
} else if (documentType && documentType.toLowerCase().includes('nda')) {
  routeToEmail = 'legal@company.com';
} else if (documentType && documentType.toLowerCase().includes('vendor')) {
  routeToEmail = 'procurement@company.com';
}

// Check renewal urgency
if (renewalDate) {
  const renewal = new Date(renewalDate);
  const today = new Date();
  const daysUntilRenewal = Math.floor((renewal - today) / (1000 * 60 * 60 * 24));

  if (daysUntilRenewal <= 30 && daysUntilRenewal >= 0) {
    alertPriority = 'High';
    status = 'Renewal Due Soon';
  }
}

return {
  json: {
    status: status,
    alertPriority: alertPriority,
    routeToEmail: routeToEmail,
    requiresApproval: contractValue > 50000 || riskFlags.length > 0
  }
};

// Get renewalDate from AI output
const renewalDate = $('legal contract analysis AI').item.json.output.renewalDate;

// Helper function: format date safely
function formatDate(dateString, hour = "09:00:00") {
  try {
    if (!dateString || dateString.toLowerCase() === "null") {
      return null; // return null if invalid or missing
    }
    return `${dateString}T${hour}Z`;
  } catch (e) {
    return null;
  }
}

// Build safe start and end times
let startDateTime = formatDate(renewalDate, "09:00:00");
let endDateTime = formatDate(renewalDate, "10:00:00");

// Optional fallback: if renewalDate is missing, set tomorrow as fallback
if (!startDateTime || !endDateTime) {
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const dateOnly = tomorrow.toISOString().split("T")[0];
  startDateTime = `${dateOnly}T09:00:00Z`;
  endDateTime = `${dateOnly}T10:00:00Z`;
}

// Build event details
return {
  json: {
    summary: "Contract Renewal Reminder",
    description: "Automatic reminder for upcoming contract renewal.",
    start: {
      dateTime: startDateTime,
      timeZone: "UTC"
    },
    end: {
      dateTime: endDateTime,
      timeZone: "UTC"
    }
  }
};

const contracts = $items("get contracts");  // Get all contract items
const today = new Date();
const upcomingRenewals = [];

for (const contract of contracts) {
  const renewalDate = contract.json['Renewal Date'] || contract.json['renewalDate'];

  // Skip if no renewal date
  if (!renewalDate) continue;

  const renewal = new Date(renewalDate);
  const daysUntil = Math.floor((renewal - today) / (1000 * 60 * 60 * 24));

  // Only include if renewal is in 30, 14, 7, or 1 day
  if ([30, 14, 7, 1].includes(daysUntil)) {
    upcomingRenewals.push({
      json: {
        ...contract.json,
        daysUntilRenewal: daysUntil,
        urgencyLevel: daysUntil <= 7 ? 'Critical' : 'Important'
      }
    });
  }
}

return upcomingRenewals;

const contracts = $input.all();
const oneWeekAgo = new Date();
oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);

const thisWeeksContracts = contracts.filter(contract => {
  const timestamp = new Date(contract.json['Timestamp']);
  return timestamp >= oneWeekAgo;
});

// Calculate statistics
const totalValue = thisWeeksContracts.reduce((sum, contract) => {
  return sum + (parseFloat(contract.json['Contract Value']) || 0);
}, 0);

const highPriority = thisWeeksContracts.filter(c => 
  c.json['Alert Status'] === 'High'
).length;

const byType = thisWeeksContracts.reduce((acc, contract) => {
  const type = contract.json['Document Type'] || 'Unknown';
  acc[type] = (acc[type] || 0) + 1;
  return acc;
}, {});

const pendingReview = thisWeeksContracts.filter(c => 
  c.json['Status'] === 'Pending Review'
).length;

return [{
  json: {
    contracts: thisWeeksContracts,
    totalProcessed: thisWeeksContracts.length,
    totalValue: totalValue,
    highPriorityCount: highPriority,
    documentTypes: byType,
    pendingReviewCount: pendingReview
  }
}];
